import React from "react";

const severityColors = {
  High: "#ff3366",
  Medium: "#f59e0b",
  Low: "#00f2fe",
};

export default function AlertsTable({ alerts = [], blockedIPs = [], onBlockIP = () => {}, onUnblockIP = () => {} }) {
  const safeAlerts = Array.isArray(alerts) ? alerts : [];
  return (
    <table
      style={{
        width: "100%",
        borderCollapse: "collapse",
        fontSize: "0.9rem",
      }}
    >
      <thead>
        <tr style={{ background: "rgba(255, 255, 255, 0.03)", borderBottom: "1px solid rgba(255, 255, 255, 0.08)", color: "#a0aec0" }}>
          <th style={{ padding: "0.75rem 0.6rem", textAlign: "left", fontWeight: "600" }}>Time</th>
          <th style={{ padding: "0.75rem 0.6rem", textAlign: "left", fontWeight: "600" }}>Source IP</th>
          <th style={{ padding: "0.75rem 0.6rem", textAlign: "left", fontWeight: "600" }}>Dest IP</th>
          <th style={{ padding: "0.75rem 0.6rem", textAlign: "left", fontWeight: "600" }}>Type</th>
          <th style={{ padding: "0.75rem 0.6rem", textAlign: "left", fontWeight: "600" }}>Severity</th>
          <th style={{ padding: "0.75rem 0.6rem", textAlign: "left", fontWeight: "600" }}>Detail</th>
          <th style={{ padding: "0.75rem 0.6rem", textAlign: "center", fontWeight: "600" }}>Mitigation</th>
        </tr>
      </thead>
      <tbody>
        {safeAlerts.length === 0 ? (
          <tr>
            <td colSpan="7" style={{ textAlign: "center", padding: "2rem", color: "#718096" }}>
              Waiting for live alerts...
            </td>
          </tr>
        ) : (
          safeAlerts.map((a) => {
            const isBlocked = blockedIPs.includes(a.source_ip);
            return (
              <tr key={a.id || Math.random()} style={{ borderBottom: "1px solid rgba(255, 255, 255, 0.05)", transition: "background 0.2s" }}>
                <td style={{ padding: "0.7rem 0.6rem", color: "#a0aec0" }}>{a.detected_at ? new Date(a.detected_at).toLocaleTimeString() : "-"}</td>
                <td style={{ padding: "0.7rem 0.6rem" }}>
                  <span style={{ fontFamily: "Consolas, monospace", color: "#e2e8f0" }}>{a.source_ip || "-"}</span>
                  {isBlocked && (
                    <span style={{ marginLeft: "0.5rem", padding: "0.2rem 0.5rem", background: "#ff3366", color: "#fff", borderRadius: "3px", fontSize: "0.7rem", fontWeight: "bold", letterSpacing: "0.5px" }}>
                      BLOCKED
                    </span>
                  )}
                </td>
                <td style={{ padding: "0.7rem 0.6rem", fontFamily: "Consolas, monospace", color: "#a0aec0" }}>{a.dest_ip || "-"}</td>
                <td style={{ padding: "0.7rem 0.6rem", color: "#cbd5e0" }}>{(a.type || "-").replace("_", " ").toUpperCase()}</td>
                <td style={{ padding: "0.7rem 0.6rem", color: severityColors[a.severity] || severityColors[(a.severity || "").charAt(0).toUpperCase() + (a.severity || "").slice(1).toLowerCase()] || "#a0aec0", fontWeight: "bold" }}>
                  {a.severity || "Unknown"}
                </td>
                <td style={{ padding: "0.7rem 0.6rem", color: "#a0aec0" }}>{a.detail || "-"}</td>
                <td style={{ padding: "0.7rem 0.6rem", textAlign: "center" }}>
                  {isBlocked ? (
                    <button
                      onClick={() => onUnblockIP(a.source_ip)}
                      style={{
                        padding: "0.3rem 0.75rem",
                        background: "transparent",
                        color: "#00f2fe",
                        border: "1px solid #00f2fe",
                        borderRadius: "4px",
                        fontSize: "0.75rem",
                        cursor: "pointer",
                        fontWeight: "600",
                        transition: "all 0.2s",
                      }}
                    >
                      Unblock
                    </button>
                  ) : (
                    <button
                      onClick={() => onBlockIP(a.source_ip)}
                      style={{
                        padding: "0.3rem 0.75rem",
                        background: (a.severity || "").toLowerCase() === "high" ? "#ff3366" : "rgba(255, 255, 255, 0.08)",
                        color: (a.severity || "").toLowerCase() === "high" ? "#fff" : "#cbd5e0",
                        border: "none",
                        borderRadius: "4px",
                        fontSize: "0.75rem",
                        cursor: "pointer",
                        fontWeight: "600",
                        boxShadow: (a.severity || "").toLowerCase() === "high" ? "0 0 10px rgba(255, 51, 102, 0.4)" : "none",
                        transition: "all 0.2s",
                      }}
                    >
                      Block IP
                    </button>
                  )}
                </td>
              </tr>
            );
          })
        )}
      </tbody>
    </table>
  );
}
